export async function handler(event) {
  const viveroId = Number(event.pathParameters.viveroId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarViveroService(viveroId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarViveroRepository, consultarViveroRepository } from './repository.mjs';

export async function consultarViveroService(viveroId, minimo) {
  const vivero = await buscarViveroRepository(viveroId);
  if (!vivero) throw new Error('Vivero no encontrado');
  const plantas = await consultarViveroRepository(viveroId, minimo);
  return { vivero, plantas };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_PLANTA, MODELO_VIVERO } from '../../models/vivero-planta.model.mjs';

export async function buscarViveroRepository(viveroId) {
  const { Item } = await MODELO_VIVERO.build(EntityRepository).get(
    { viveroId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarViveroRepository(viveroId, minimo) {
  const { Items = [] } = await MODELO_PLANTA.build(EntityRepository).query(
    { index: 'PorVivero', partition: viveroId },
    { filters: { Planta: { attr: 'alturaCm', gte: minimo } } }
  );
  return Items;
}
